// TransformCPIMField32 reproduces the recovered first 32-byte CPIM plaintext
// field. Input contains semantic bytes after removing native source-address
// encoding. Its wider protocol role remains unresolved.
func TransformCPIMField32(input [32]byte) [32]byte {
	feedback := [4]uint32{0x4ae73560, 0x75810d5c, 0x456727bc, 0xbe15aee5}
	var output [32]byte
	for i := 0; i < 2; i++ {
		var block [16]byte
		copy(block[:], input[16*i:16*i+16])
		transformed, next := helperRound(block, feedback)
		feedback = next
		copy(output[16*i:16*i+16], transformed[:])
	}
	return output
}
